theorem tensorChange_homogeneous (A : Matrix (Fin 3) (Fin 3) R) {n : ℕ}
    {P : AuxTensor (R := R) (M := M)} (hP : TensorHomogeneous n P) :
    TensorHomogeneous n (tensorChange A P)

theorem tensorDivideFirst_homogeneous {n : ℕ}
    {P : AuxTensor (R := R) (M := M)} (hP : TensorHomogeneous (n + 1) P) :
    TensorHomogeneous n (tensorDivideFirst P)

theorem IsPolynomialFamily.add {f g : (ι → K) → V}
    (hf : IsPolynomialFamily f) (hg : IsPolynomialFamily g) :
    IsPolynomialFamily (fun a => f a + g a)

theorem IsPolynomialFamily.prod_mk {f : (ι → K) → V} {g : (ι → K) → W}
    (hf : IsPolynomialFamily f) (hg : IsPolynomialFamily g) :
    IsPolynomialFamily (fun a => (f a, g a))

theorem IsPolynomialFamily.smul {f : (ι → K) → K} {g : (ι → K) → V}
    (hf : IsPolynomialFamily f) (hg : IsPolynomialFamily g) :
    IsPolynomialFamily (fun a => f a • g a)

theorem chart_sup_eq_supported :
    (chartU (K := K)) ⊔ chartV =
      AddMonoidAlgebra.supported K K {e : ℤ × ℤ | 0 ≤ e.2 ∨ 0 ≤ e.1}

theorem residual_nonpos_of_aCount_nonpos {d r e : ℕ}
    (hr : 3 ≤ r) (ha : aCount d r ≤ 0) (he : 1 ≤ e) :
    residual d r e ≤ 0

theorem homogeneousComponent_ideal_eq_zero (j : ℕ) (hj : j < d)
    (W : Submodule K (Poly K n)) (hW : W ≤ Forms K n d) {p : Poly K n}
    (hp : p ∈ Ideal.span (W : Set (Poly K n))) : homogeneousComponent j p = 0

theorem IsPolynomialFamily.sub {f g : (ι → K) → V}
    (hf : IsPolynomialFamily f) (hg : IsPolynomialFamily g) :
    IsPolynomialFamily (fun a => f a - g a)

theorem range_uFreeEmbedding :
    LinearMap.range (uFreeEmbedding (K := K) (ι := ι)) =
      Finsupp.supported K K {e : ι × (ℤ × ℤ) | 0 ≤ e.2.2}

theorem range_vFreeEmbedding :
    LinearMap.range (vFreeEmbedding (K := K) (ι := ι)) =
      Finsupp.supported K K {e : ι × (ℤ × ℤ) | 0 ≤ e.2.1}

theorem choppedHilbertFunction_eq_point_of_piece_eq {p d t : ℕ}
    (a : PointCoordinates K p) (h : ChopEqualsPointPiece K a d t) :
    choppedHilbertFunction a d t = pointHilbertFunction K a t

theorem pointDegreeSpace_eq_chop_generating_degree {p d : ℕ}
    (a : PointCoordinates K p) :
    pointDegreeSpace K a d = idealDegreeSpace (choppedIdeal K a d) d

theorem affineCofactorIdeal_le_selectedAffineEvaluation_ker {c : ℕ}
    (δ : Fin (c + 1) → ℕ) (α β : RootIndex δ → K) :
    affineCofactorIdeal δ α β ≤ RingHom.ker (selectedAffineEvaluation δ α β).toRingHom

theorem coefficientSpecialization_isPolynomialFamily {ι R : Type*}
    [CommRing R] [Algebra K R] (P : MvPolynomial ι R) :
    IsPolynomialFamily (fun u : ι → K => coefficientSpecialization u P)

@[simp] theorem idealFormPiece_pointIdeal {p : ℕ}
    (a : PointCoordinates K p) (t : ℕ) :
    idealFormPiece (pointIdeal K a) t = pointDegreePiece K a t

@[simp] theorem idealFormQuotientMap_ker {n : ℕ}
    (I : Ideal (Poly K n)) (t : ℕ) :
    (idealFormQuotientMap I t).ker = idealFormPiece I t

@[simp] theorem idealQuotientHilbertFunction_pointIdeal {p : ℕ}
    (a : PointCoordinates K p) (t : ℕ) :
    idealQuotientHilbertFunction (pointIdeal K a) t = pointHilbertFunction K a t

theorem form_cut_of_le (I : Ideal (Poly K 3)) (N t : ℕ) (hNt : N ≤ t)
    (hcut : ∀ f : Forms K 3 N, f.val ∈ I ⊔ Ideal.span {X (R := K) 2})
    (f : Forms K 3 t) : f.val ∈ I ⊔ Ideal.span {X (R := K) 2}

theorem intermediate_max_eq_point_iff {d p e : ℕ}
    (hp : p < N d) (hr : 3 ≤ N d - p) (he : 1 ≤ e) :
    max p (N (d + e) - (N d - p) * N e) = p ↔ cutoff d (N d - p) ≤ e

theorem linearMatrixMap_polynomial_family {ι : Type*}
    (F : (ι → K) → LinearMatrix K a c) (hF : IsPolynomialFamily F) (t : ℕ) :
    IsPolynomialFamily (fun u => linearMatrixMap (F u) t)

theorem affinePresentation_plane_apply {p : ℕ}
    (φ : Poly K 2 →ₐ[K] (Fin p → K)) (f : Poly K 3) (i : Fin p) :
    φ (affineDehom f) i = eval (chartPoint K (affinePresentationCoordinates φ) i) f

theorem cofactorIdeal_le_principal_of_common_divisor
    {R : Type*} [CommRing R] (B : Matrix (Fin (c + 1)) (Fin c) R) (u : R)
    (hu : ∀ i, u ∣ maximalMinor B i) : cofactorIdeal B ≤ Ideal.span {u}

theorem homogeneous_mul_mem_signedForms {d : ℕ} {t : ℤ} {p q : BinaryRing K}
    (hp : p.IsHomogeneous d) (hq : q ∈ signedForms K 2 t) :
    p * q ∈ signedForms K 2 (t + d)

theorem polynomialLaurentGrade_mul {d e : ℤ} {p q : BinaryLaurent K}
    (hp : p ∈ polynomialLaurentGrade d) (hq : q ∈ polynomialLaurentGrade e) :
    p * q ∈ polynomialLaurentGrade (d + e)

theorem quarticSubstitution_mem_signedForms {t : ℤ} {p : BinaryRing K}
    (hp : p ∈ signedForms K 2 t) :
    quarticSubstitution K p ∈ signedForms K 2 (4 * t)

theorem weightedPolynomial_linearForm {w : Fin 3 → ℕ} {d : ℤ} {a : Fin 3 → CyclicCubicRing (BinaryRing K) F}
    (ha : ∀ i, WeightedScalar F w d (a i)) :
    WeightedPolynomial F w d (linearForm a)

theorem weightedPolynomial_mul {w : Fin 3 → ℕ} {d e : ℤ} {p q : Aux (CyclicCubicRing (BinaryRing K) F)}
    (hp : WeightedPolynomial F w d p) (hq : WeightedPolynomial F w e q) :
    WeightedPolynomial F w (d + e) (p * q)

theorem weightedPolynomial_pow {w : Fin 3 → ℕ} {d : ℤ} {p : Aux (CyclicCubicRing (BinaryRing K) F)}
    (hp : WeightedPolynomial F w d p) (n : ℕ) :
    WeightedPolynomial F w (n * d) (p ^ n)

theorem weightedScalar_add {w : Fin 3 → ℕ} {d : ℤ} {r s : CyclicCubicRing (BinaryRing K) F}
    (hr : WeightedScalar F w d r) (hs : WeightedScalar F w d s) :
    WeightedScalar F w d (r + s)

theorem weightedScalar_coefficient {w : Fin 3 → ℕ} {d : ℕ} {b : BinaryRing K}
    (hb : b.IsHomogeneous d) :
    WeightedScalar F w d (cyclicCoefficientHom F b)

theorem weightedScalar_mul {w : Fin 3 → ℕ} {d e : ℤ} {r s : CyclicCubicRing (BinaryRing K) F}
    (hr : WeightedScalar F w d r) (hs : WeightedScalar F w e s) :
    WeightedScalar F w (d + e) (r * s)

theorem weightedScalar_pow {w : Fin 3 → ℕ} {d : ℤ} {r : CyclicCubicRing (BinaryRing K) F}
    (hr : WeightedScalar F w d r) (n : ℕ) :
    WeightedScalar F w (n * d) (r ^ n)

theorem weightedScalar_sum {ι : Type*} (s : Finset ι) {w : Fin 3 → ℕ} {d : ℤ}
    {r : ι → CyclicCubicRing (BinaryRing K) F} (hr : ∀ i ∈ s, WeightedScalar F w d (r i)) :
    WeightedScalar F w d (∑ i ∈ s, r i)

theorem weightedVector_add {w : Fin 3 → ℕ} {t : ℤ} {m n : BinaryVector K}
    (hm : WeightedVector w t m) (hn : WeightedVector w t n) :
    WeightedVector w t (m + n)

theorem weightedVector_binary_smul {w : Fin 3 → ℕ} {t : ℤ} {d : ℕ}
    {b : BinaryRing K} {m : BinaryVector K}
    (hb : b.IsHomogeneous d) (hm : WeightedVector w t m) :
    WeightedVector w (t + d) (b • m)

theorem weightedVector_sum {ι : Type*} (s : Finset ι) {w : Fin 3 → ℕ} {t : ℤ}
    {m : ι → BinaryVector K} (hm : ∀ i ∈ s, WeightedVector w t (m i)) :
    WeightedVector w t (∑ i ∈ s, m i)
